const matches = $input.all();
if (matches.length === 0) {
  return [{ json: {
    status: 'RESOLVED',
    data: { mes: null, lineas_priorizadas: [], notas_para_agente: '' },
    message_to_agent: 'No hay configuración mensual activa. Procedé sin priorización específica.',
    trace_id: $execution.id
  } }];
}
const cfg = matches[0].json;

// FIX SD-11 (auditoria-2026-07-01.md): 'Líneas priorizadas' es multilineText
// en Airtable (no Link a Líneas de Producto, como asumía este código antes)
// -> llega como STRING, no array. Antes `.join(', ')` sobre un string
// crasheaba el nodo (TypeError) apenas alguien completara el campo — hoy
// está dormido solo porque el único record de Config Mensual lo tiene vacío.
// Fix defensivo: normaliza a array sea cual sea la forma real del dato, sin
// requerir cambiar el tipo del field en Airtable.
const rawLineas = cfg['Líneas priorizadas'];
const lineasPriorizadas = Array.isArray(rawLineas)
  ? rawLineas
  : (typeof rawLineas === 'string' && rawLineas.trim()
      ? rawLineas.split(',').map(s => s.trim()).filter(Boolean)
      : []);

return [{ json: {
  status: 'RESOLVED',
  data: {
    mes: cfg.Mes || '',
    lineas_priorizadas: lineasPriorizadas,
    notas_para_agente: cfg['Notas para agente'] || ''
  },
  message_to_agent: cfg['Notas para agente']
    ? `Líneas priorizadas este mes: ${lineasPriorizadas.join(', ')}. Nota: ${cfg['Notas para agente']}`
    : 'Sin priorización particular este mes.',
  trace_id: $execution.id
} }];
